def transform(grid):
    """Replace each four-connected singleton by its cardinal-neighbor majority color."""
    h, w = len(grid), len(grid[0])
    seen = set()
    singles = []
    for r in range(h):
        for c in range(w):
            if (r,c) in seen:
                continue
            color = grid[r][c]
            todo = [(r,c)]
            seen.add((r,c))
            comp = []
            while todo:
                y,x = todo.pop()
                comp.append((y,x))
                for ny,nx in ((y-1,x),(y,x-1),(y,x+1),(y+1,x)):
                    if 0 <= ny < h and 0 <= nx < len(grid[ny]) and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); todo.append((ny,nx))
            if len(comp) == 1:
                singles.append(comp[0])
    out = [row[:] for row in grid]
    for r,c in singles:
        counts = {}
        for y,x in ((r-1,c),(r,c-1),(r,c+1),(r+1,c)):
            if 0 <= y < h and 0 <= x < w:
                v = grid[y][x]
                counts[v] = counts.get(v,0)+1
        best = max(counts.values())
        tied = {v for v,n in counts.items() if n == best}
        if len(tied) == 1:
            out[r][c] = next(iter(tied))
        else:
            # Resolve boundary ties in favor of the less frequent region/object color.
            totals = {v: sum(row.count(v) for row in grid) for v in tied}
            out[r][c] = min(tied, key=lambda v:(totals[v],v))
    return out

